from solution import greatest_common_divisor
import math
import pytest
from hypothesis import given
import hypothesis.strategies as st


def naive_gcd(a: int, b: int) -> int:
    """Obviously correct reference: largest d in [1, min(a,b)] dividing both."""
    m = min(a, b)
    best = 1
    for d in range(1, m + 1):
        if a % d == 0 and b % d == 0:
            best = d
    return best


# --- concrete examples from spec docstring ---

def test_example_3_5_is_1():
    assert greatest_common_divisor(3, 5) == 1


def test_example_25_15_is_5():
    assert greatest_common_divisor(25, 15) == 5


# --- definitional properties ---

@given(
    a=st.integers(min_value=1, max_value=200),
    b=st.integers(min_value=1, max_value=200),
)
def test_result_divides_both(a, b):
    g = greatest_common_divisor(a, b)
    assert type(g) == int
    assert a % g == 0
    assert b % g == 0


@given(
    a=st.integers(min_value=1, max_value=200),
    b=st.integers(min_value=1, max_value=200),
)
def test_result_is_positive_and_bounded(a, b):
    g = greatest_common_divisor(a, b)
    assert g >= 1
    assert g <= min(a, b)


@given(
    a=st.integers(min_value=1, max_value=120),
    b=st.integers(min_value=1, max_value=120),
)
def test_result_is_greatest_common_divisor(a, b):
    g = greatest_common_divisor(a, b)
    # no common divisor exceeds g; every common divisor divides g's range check
    for d in range(1, min(a, b) + 1):
        if a % d == 0 and b % d == 0:
            assert d <= g


@given(
    a=st.integers(min_value=1, max_value=200),
    b=st.integers(min_value=1, max_value=200),
)
def test_equivalence_to_naive_reference(a, b):
    assert greatest_common_divisor(a, b) == naive_gcd(a, b)


@given(
    a=st.integers(min_value=1, max_value=1000),
    b=st.integers(min_value=1, max_value=1000),
)
def test_equivalence_to_math_gcd_oracle(a, b):
    assert greatest_common_divisor(a, b) == math.gcd(a, b)


# --- algebraic / metamorphic properties ---

@given(
    a=st.integers(min_value=1, max_value=500),
    b=st.integers(min_value=1, max_value=500),
)
def test_symmetry(a, b):
    assert greatest_common_divisor(a, b) == greatest_common_divisor(b, a)


@given(a=st.integers(min_value=1, max_value=500))
def test_self_gcd_is_self(a):
    assert greatest_common_divisor(a, a) == a


@given(x=st.integers(min_value=1, max_value=500))
def test_one_is_identity(x):
    assert greatest_common_divisor(1, x) == 1
    assert greatest_common_divisor(x, 1) == 1


@given(n=st.integers(min_value=1, max_value=500))
def test_consecutive_integers_are_coprime(n):
    assert greatest_common_divisor(n, n + 1) == 1


@given(
    a=st.integers(min_value=1, max_value=100),
    b=st.integers(min_value=1, max_value=100),
    k=st.integers(min_value=1, max_value=20),
)
def test_scaling_property(a, b, k):
    assert greatest_common_divisor(k * a, k * b) == k * greatest_common_divisor(a, b)


@given(
    a=st.integers(min_value=1, max_value=200),
    m=st.integers(min_value=1, max_value=20),
)
def test_multiple_property(a, m):
    # a divides a*m, so gcd must be a
    assert greatest_common_divisor(a, a * m) == a
    assert greatest_common_divisor(a * m, a) == a


@given(
    a=st.integers(min_value=1, max_value=300),
    b=st.integers(min_value=1, max_value=300),
)
def test_euclidean_reduction_step(a, b):
    # gcd(a, b) == gcd(b, a mod b) when remainder nonzero; == b when zero
    r = a % b
    if r == 0:
        assert greatest_common_divisor(a, b) == b
    else:
        assert greatest_common_divisor(a, b) == greatest_common_divisor(b, r)


@given(
    a=st.integers(min_value=1, max_value=100),
    b=st.integers(min_value=1, max_value=100),
    c=st.integers(min_value=1, max_value=100),
)
def test_associativity(a, b, c):
    left = greatest_common_divisor(greatest_common_divisor(a, b), c)
    right = greatest_common_divisor(a, greatest_common_divisor(b, c))
    assert left == right == math.gcd(math.gcd(a, b), c)


@given(
    a=st.integers(min_value=1, max_value=200),
    b=st.integers(min_value=1, max_value=200),
)
def test_common_divisor_divides_result(a, b):
    g = greatest_common_divisor(a, b)
    for d in range(1, min(a, b) + 1):
        if a % d == 0 and b % d == 0:
            assert g % d == 0


def test_boundary_min_values():
    assert greatest_common_divisor(1, 1) == 1
    assert greatest_common_divisor(1, 2) == 1
    assert greatest_common_divisor(2, 1) == 1
    assert greatest_common_divisor(2, 2) == 2


def test_boundary_primes_and_powers():
    assert greatest_common_divisor(13, 17) == 1
    assert greatest_common_divisor(8, 12) == 4
    assert greatest_common_divisor(100, 10) == 10
    assert greatest_common_divisor(48, 18) == 6
    assert greatest_common_divisor(7, 7) == 7
    assert greatest_common_divisor(2, 4) == 2
    assert greatest_common_divisor(9, 6) == 3
